actions.action:
// Economic nexus established per Wayfair - filing required
// Oregon threshold: $750,000 in Oregon sales (higher than typical)
// Apportionment will be calculated by tables 7000-7500

// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate OR state additions
            double additions = 0.0;

            // OR requires addback of:
            // - Federal interest income (taxable to OR)
            // - IRC 199A deduction (OR may not conform depending on year)
            // - State income tax refunds
            // - Certain bonus depreciation amounts (depends on year)
            // - Expenses related to exempt income

            // Example additions (would be calculated from entity fields):
            // additions += revenue.federal_bond_interest;
            // additions += result.section_199a_deduction;
            // additions += result.state_tax_refunds;

            apportionment.state_additions = additions;

            // Calculate OR state subtractions
            double subtractions = 0.0;

            // OR allows subtraction of:
            // - OR municipal bond interest (exempt for OR purposes)
            // - OR net operating loss deduction (if applicable)
            // - Dividends from certain subsidiaries
            // - Federal income taxes (if included in federal taxable income)

            // Example subtractions (would be calculated from entity fields):
            // subtractions += revenue.or_municipal_interest;
            // subtractions += result.or_nol_deduction;
            // subtractions += result.qualified_dividend_deduction;

            apportionment.state_subtractions = subtractions;

            // Financial institutions use 7.6% rate instead of 6.6%
            double excise_tax =
              apportionment.state_taxable_income * result.or_financial_institution_rate;

            // Calculate minimum tax based on Oregon sales (ORS 317.090)
            double or_sales = result.or_sales_in_oregon;
            double minimum_tax = 150.0; // Default minimum

            if (or_sales >= 100000000.0) {
              minimum_tax = 100000.0;
            } else if (or_sales >= 75000000.0) {
              minimum_tax = 75000.0;
            } else if (or_sales >= 50000000.0) {
              minimum_tax = 50000.0;
            } else if (or_sales >= 25000000.0) {
              minimum_tax = 30000.0;
            } else if (or_sales >= 10000000.0) {
              minimum_tax = 15000.0;
            } else if (or_sales >= 7000000.0) {
              minimum_tax = 7500.0;
            } else if (or_sales >= 5000000.0) {
              minimum_tax = 4000.0;
            } else if (or_sales >= 3000000.0) {
              minimum_tax = 2000.0;
            } else if (or_sales >= 2000000.0) {
              minimum_tax = 1500.0;
            } else if (or_sales >= 1000000.0) {
              minimum_tax = 1000.0;
            } else if (or_sales >= 500000.0) {
              minimum_tax = 500.0;
            }

            result.or_minimum_tax = minimum_tax;

            // Tax liability is GREATER of excise tax or minimum tax
            apportionment.state_tax = Math.max(excise_tax, minimum_tax);

            // Subtract state credits
            apportionment.state_tax =
              Math.max(minimum_tax, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // Regular corporations use 6.6% flat rate
            double excise_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Calculate minimum tax based on Oregon sales (ORS 317.090)
            double or_sales = result.or_sales_in_oregon;
            double minimum_tax = 150.0; // Default minimum

            if (or_sales >= 100000000.0) {
              minimum_tax = 100000.0;
            } else if (or_sales >= 75000000.0) {
              minimum_tax = 75000.0;
            } else if (or_sales >= 50000000.0) {
              minimum_tax = 50000.0;
            } else if (or_sales >= 25000000.0) {
              minimum_tax = 30000.0;
            } else if (or_sales >= 10000000.0) {
              minimum_tax = 15000.0;
            } else if (or_sales >= 7000000.0) {
              minimum_tax = 7500.0;
            } else if (or_sales >= 5000000.0) {
              minimum_tax = 4000.0;
            } else if (or_sales >= 3000000.0) {
              minimum_tax = 2000.0;
            } else if (or_sales >= 2000000.0) {
              minimum_tax = 1500.0;
            } else if (or_sales >= 1000000.0) {
              minimum_tax = 1000.0;
            } else if (or_sales >= 500000.0) {
              minimum_tax = 500.0;
            }

            result.or_minimum_tax = minimum_tax;

            // Tax liability is GREATER of excise tax or minimum tax
            apportionment.state_tax = Math.max(excise_tax, minimum_tax);

            // Subtract state credits (but cannot reduce below minimum tax)
            apportionment.state_tax =
              Math.max(minimum_tax, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // No excise tax, but MINIMUM TAX STILL APPLIES
            // Calculate minimum tax based on Oregon sales
            double or_sales = result.or_sales_in_oregon;
            double minimum_tax = 150.0; // Default minimum

            if (or_sales >= 100000000.0) {
              minimum_tax = 100000.0;
            } else if (or_sales >= 75000000.0) {
              minimum_tax = 75000.0;
            } else if (or_sales >= 50000000.0) {
              minimum_tax = 50000.0;
            } else if (or_sales >= 25000000.0) {
              minimum_tax = 30000.0;
            } else if (or_sales >= 10000000.0) {
              minimum_tax = 15000.0;
            } else if (or_sales >= 7000000.0) {
              minimum_tax = 7500.0;
            } else if (or_sales >= 5000000.0) {
              minimum_tax = 4000.0;
            } else if (or_sales >= 3000000.0) {
              minimum_tax = 2000.0;
            } else if (or_sales >= 2000000.0) {
              minimum_tax = 1500.0;
            } else if (or_sales >= 1000000.0) {
              minimum_tax = 1000.0;
            } else if (or_sales >= 500000.0) {
              minimum_tax = 500.0;
            }

            result.or_minimum_tax = minimum_tax;
            apportionment.state_tax = minimum_tax;

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
